    private static let blob: Data = Data(base64Encoded: b64)!

    private static func entry(_ name: String) -> Entry {
        entries.first { $0.name == name }!
    }

    static func geometry(_ name: String) -> SCNGeometry {
        let e = entry(name)
        var verts = [Float](repeating: 0, count: e.nv * 3)
        var norms = [Float](repeating: 0, count: e.nv * 3)
        var idx = [UInt16](repeating: 0, count: e.nf * 3)
        blob.withUnsafeBytes { ptr in
            let base = ptr.baseAddress!
            let q = base.advanced(by: e.off).assumingMemoryBound(to: UInt16.self)
            for i in 0..<e.nv {
                verts[i*3+0] = e.min.x + Float(q[i*3+0]) / 65535.0 * e.span.x
                verts[i*3+1] = e.min.y + Float(q[i*3+1]) / 65535.0 * e.span.y
                verts[i*3+2] = e.min.z + Float(q[i*3+2]) / 65535.0 * e.span.z
            }
            let ip = base.advanced(by: e.off + e.nv * 6).assumingMemoryBound(to: UInt16.self)
            for i in 0..<e.nf * 3 { idx[i] = ip[i] }
        }
        // smooth vertex normals from face normals
        for f in 0..<e.nf {
            let a = Int(idx[f*3]), b = Int(idx[f*3+1]), c = Int(idx[f*3+2])
            let ax = verts[a*3], ay = verts[a*3+1], az = verts[a*3+2]
            let bx = verts[b*3], by = verts[b*3+1], bz = verts[b*3+2]
            let cx = verts[c*3], cy = verts[c*3+1], cz = verts[c*3+2]
            let ux = bx-ax, uy = by-ay, uz = bz-az
            let vx = cx-ax, vy = cy-ay, vz = cz-az
            let nx = uy*vz-uz*vy, ny = uz*vx-ux*vz, nz = ux*vy-uy*vx
            for v in [a, b, c] {
                norms[v*3] += nx; norms[v*3+1] += ny; norms[v*3+2] += nz
            }
        }
        for i in 0..<e.nv {
            let nx = norms[i*3], ny = norms[i*3+1], nz = norms[i*3+2]
            let l = max(1e-6, sqrtf(nx*nx + ny*ny + nz*nz))
            norms[i*3] = nx/l; norms[i*3+1] = ny/l; norms[i*3+2] = nz/l
        }
        let vData = Data(bytes: &verts, count: e.nv * 12)
        let nData = Data(bytes: &norms, count: e.nv * 12)
        let iData = Data(bytes: &idx, count: e.nf * 6)
        let vSrc = SCNGeometrySource(data: vData, semantic: .vertex, vectorCount: e.nv,
                                     usesFloatComponents: true, componentsPerVector: 3,
                                     bytesPerComponent: 4, dataOffset: 0, dataStride: 12)
        let nSrc = SCNGeometrySource(data: nData, semantic: .normal, vectorCount: e.nv,
                                     usesFloatComponents: true, componentsPerVector: 3,
                                     bytesPerComponent: 4, dataOffset: 0, dataStride: 12)
        let el = SCNGeometryElement(data: iData, primitiveType: .triangles,
                                    primitiveCount: e.nf, bytesPerIndex: 2)
        return SCNGeometry(sources: [vSrc, nSrc], elements: [el])
    }

    static func node(_ name: String, material: SCNMaterial) -> SCNNode {
        let g = geometry(name)
        g.materials = [material]
        let n = SCNNode(geometry: g)
        n.name = "mesh_" + name
        return n
    }
}
